const cards=[
{n:'01',cat:'national',grades:'5–8',ar:{title:'رمز وقيمة',element:'الهوية الوطنية | الولاء للوطن والانتماء له',challenge:'تختار المعلمة مباشرة من هذه الرموز الظاهرة على البطاقة: النخلة، الصقر، المجلس، البحر، العلم، القهوة العربية. تختار المجموعة رمزاً واحداً، وتحدد معناه وسلوكاً مدرسياً يعكس قيمته، ثم تصفه دون ذكر اسمه ليخمنه الصف.',link:'الاعتزاز بالهوية لا يقتصر على معرفة الرموز؛ بل يظهر عندما نفهم معانيها ونترجمها إلى سلوك.',evidence:'اسم الرمز + قيمته + سلوك مدرسي واحد.',impact:'كيف أجعل انتمائي للوطن ظاهراً في أفعالي؟'},en:{title:'Symbol & Value',element:'National Identity | Loyalty and Belonging',challenge:'Use one of the symbols shown here: palm tree, falcon, majlis, sea, UAE flag or Arabic coffee. The group chooses one, explains what it represents and gives one school behaviour that reflects its meaning, then describes it without naming it for the class to guess.',link:'Pride in identity is more than recognising symbols; it appears when learners understand their meaning and translate it into behaviour.',evidence:'Symbol + value + one school behaviour.',impact:'How can I make my belonging to the UAE visible through my actions?'}},
{n:'02',cat:'national',grades:'7–12',ar:{title:'مهمة 2071',element:'الهوية الوطنية | الانتماء + روح المبادرة والمثابرة',challenge:'تصنع المجموعة خبراً من عام 2071 عن إنجاز تتمنى أن تحققه الإمارات، وتوضح المشكلة التي حُلّت وما الذي فعله جيلهم للوصول إليه.',link:'يربط الميثاق بين الانتماء والطموح؛ فالمتعلم شريك في بناء المستقبل.',evidence:'خبر قصير + عنصر من الميثاق + خطوة تبدأ الآن.',impact:'ما الخطوة التي أستطيع أن أبدأ بها من الآن لخدمة مستقبل وطني؟'},en:{title:'Mission 2071',element:'National Identity | Belonging + Initiative & Perseverance',challenge:'Create a short news report from 2071 about a future UAE achievement. Explain the problem solved and what your generation did to make it happen.',link:'The Charter connects belonging with ambition; learners are contributors to the future, not only recipients of it.',evidence:'Short news report + Charter element + one action to start now.',impact:'What can I start doing today to contribute to my country’s future?'}},
{n:'03',cat:'national',grades:'5–9',ar:{title:'كلمة من بيتنا',element:'الهوية الوطنية | اللغة العربية + الأسرة الممتدة',challenge:'تختار كل طالبة كلمة أو تعبيراً عربياً تسمعه في البيت أو من الكبار، وتشرح معناه أو موقفاً يستخدم فيه. تختار المجموعة كلمة واحدة وتحولها إلى بطاقة «كلمة نحافظ عليها».',link:'يعزز الميثاق الاعتزاز باللغة العربية ودور الأسرة الممتدة في نقل الهوية والقيم بين الأجيال.',evidence:'كلمة عربية + معناها + مصدر تعلمها.',impact:'كيف تساعد الأسرة واللغة في حفظ هويتنا؟'},en:{title:'A Word from Home',element:'National Identity | Arabic Language + Extended Family',challenge:'Each student shares an Arabic word or expression heard at home or from older family members, explains its meaning or use, then the group selects one as a “word worth preserving.”',link:'The Charter highlights pride in Arabic and the role of the extended family in passing identity and values across generations.',evidence:'Arabic word + meaning + where it was learned.',impact:'How do family and language help preserve our identity?'}},
{n:'04',cat:'national',grades:'7–12',ar:{title:'قرار النزاهة',element:'الهوية الوطنية | النزاهة',challenge:'اختاري موقفاً من الشاشة: (1) وجدتِ شيئاً ليس لكِ. (2) رأيتِ زميلة تغش. (3) حصلتِ على درجة بالخطأ. (4) كسرتِ شيئاً ولم يرك أحد. تختار المجموعة قراراً ثم تختبره: هل هو صادق؟ عادل؟ ويمكنني تحمل مسؤوليته؟',link:'النزاهة تظهر عندما نختار الصحيح حتى عندما لا يراقبنا أحد.',evidence:'قرار + تبرير وفق 3 أسئلة للنزاهة.',impact:'ماذا أفعل عندما يكون القرار الصحيح أصعب؟'},en:{title:'Integrity Decision',element:'National Identity | Integrity',challenge:'Choose a scenario from the screen: (1) You find something that is not yours. (2) You see a classmate cheating. (3) You receive a mark by mistake. (4) You break something and nobody sees you. Groups choose a response, then test it: Is it honest? Is it fair? Can I take responsibility for it?',link:'Integrity is demonstrated when we choose what is right even when nobody is watching.',evidence:'Decision + justification using three integrity checks.',impact:'What do I do when the right decision is the harder one?'}},
{n:'05',cat:'national',grades:'5–12',ar:{title:'أثر بلا اسم',element:'الهوية الوطنية | الكرم والتواضع + الاحترام والإحسان',challenge:'تختار المجموعة مكاناً في المدرسة وتصمم عملاً صغيراً من الإحسان يمكن تنفيذه دون تصوير أو إعلان اسم صاحبه، ثم تختار ما يمكن تنفيذه فوراً.',link:'يربط الميثاق الكرم والتواضع والإحسان بالفعل نفسه لا بالثناء.',evidence:'فعل إحسان قابل للتنفيذ + المستفيد.',impact:'هل يبقى العمل قيّماً إذا لم يعرف أحد أنني قمت به؟'},en:{title:'Impact Without a Name',element:'National Identity | Generosity & Humility + Respect & Kindness',challenge:'Choose a school location and design a small act of kindness that can be done without taking credit or posting about it. Select one that can be carried out immediately.',link:'The Charter connects generosity, humility and kindness with the act itself rather than public recognition.',evidence:'One doable act of kindness + who benefits.',impact:'Does an act remain valuable if nobody knows I did it?'}},
{n:'06',cat:'national',grades:'5–12',ar:{title:'غيّر الخطة',element:'الهوية الوطنية | المرونة والتكيف',challenge:'المهمة: جهزوا خطة من 3 خطوات لتنظيم عرض صفّي قصير. بعد دقيقة تختار المعلمة مفاجأة من الشاشة: الوقت أصبح دقيقتين فقط، متحدثة الفريق غائبة، أو يجب أن يشارك الجميع. عدّلوا الخطة دون تغيير الهدف.',link:'المرونة والتكيف تعنيان تعديل الطريق عند تغير الظروف مع المحافظة على الهدف.',evidence:'الخطة الأصلية + التعديل + سبب التغيير.',impact:'كيف أتكيف دون أن أتخلى عن هدفي؟'},en:{title:'Change the Plan',element:'National Identity | Flexibility & Adaptability',challenge:'Task: make a three-step plan for a short class presentation. After one minute, the teacher chooses a surprise shown here: only two minutes remain, the team speaker is absent, or everyone must participate. Adapt the plan without changing the goal.',link:'Adaptability means changing the route when circumstances change while keeping sight of the goal.',evidence:'Original plan + adjustment + reason.',impact:'How can I adapt without giving up on my goal?'}},
{n:'07',cat:'national',grades:'5–12',ar:{title:'ابدئي الآن',element:'الهوية الوطنية | روح المبادرة والمثابرة',challenge:'تختار المجموعة مشكلة صغيرة حقيقية في الصف. لا يُقبل الاكتفاء بالاقتراح؛ عليها تنفيذ أول خطوة خلال الحصة نفسها.',link:'روح المبادرة تبدأ بالفعل، والمثابرة تعني الاستمرار بعد البداية.',evidence:'المشكلة + أول خطوة منفذة فعلياً.',impact:'ما الفرق بين صاحب الفكرة وصاحب المبادرة؟'},en:{title:'Start Now',element:'National Identity | Initiative & Perseverance',challenge:'Choose a small real classroom problem. Suggesting a solution is not enough: the group must complete the first practical step during the same lesson.',link:'Initiative begins with action, while perseverance means continuing after the first step.',evidence:'Problem + first action actually completed.',impact:'What is the difference between having an idea and taking initiative?'}},
{n:'08',cat:'traits',grades:'5–9',ar:{title:'فريق تحت الضغط',element:'السمات | العمل الجماعي + التنظيم الذاتي والانضباط',challenge:'لدى الفريق 7 دقائق لحل التحدي التالي شفهياً: صمموا «صفاً مثالياً» من خمس قواعد فقط. وزعوا الأدوار: قائدة، ضابطة وقت، كاتبة، متحدثة، ومراجعة. بعد 3 دقائق تتغير القائدة. النجاح يقاس بالتعاون والالتزام بالأدوار والوقت.',link:'يركز الميثاق على متعلم ينظم نفسه ويعمل مع الآخرين لتحقيق هدف مشترك.',evidence:'منتج الفريق + التزام بالأدوار + إنجاز في الوقت.',impact:'ما السلوك الذي جعل فريقنا أفضل؟'},en:{title:'Team Under Pressure',element:'Traits | Teamwork + Self-Regulation & Discipline',challenge:'Teams have seven minutes to solve this class-ready task: design an “ideal classroom” using only five rules. Assign roles: leader, timekeeper, recorder, speaker and checker. After three minutes, change the leader. Success depends on teamwork, roles and time management.',link:'The Charter promotes learners who regulate themselves and work effectively with others toward a shared goal.',evidence:'Team product + role commitment + on-time completion.',impact:'Which behaviour made our team stronger?'}},
{n:'09',cat:'traits',grades:'5–12',ar:{title:'دقيقة ضبط النفس',element:'السمات | التنظيم الذاتي والانضباط',challenge:'اختاري موقفاً من الشاشة: زميلة قاطعتك، خسرت مجموعتك نقطة، لم تفهمي التعليمات، أو أخطأ أحد في حقك. طبقي: أتوقف – أفكر – أقرر، ثم اشرحي كيف يمنع هذا التسلسل رد الفعل المتسرع.',link:'التنظيم الذاتي يعني أن أتحكم في استجابتي قبل أن يتحكم الموقف فيّ.',evidence:'قرار هادئ لموقف واحد + السبب.',impact:'متى يكون التوقف لثوانٍ علامة قوة؟'},en:{title:'One Minute of Self-Control',element:'Traits | Self-Regulation & Discipline',challenge:'Choose a scenario shown here: a classmate interrupts you, your group loses a point, you do not understand the instructions, or someone treats you unfairly. Use “Pause – Think – Decide” and explain how it prevents an impulsive response.',link:'Self-regulation means managing my response before the situation manages me.',evidence:'One calm decision + reason.',impact:'When can pausing for a few seconds be a sign of strength?'}},
{n:'10',cat:'traits',grades:'5–12',ar:{title:'أنا أستطيع',element:'السمات | الثقة بالنفس',challenge:'تختار الطالبة واحداً من التحديات الظاهرة: اشرحي فكرة مفيدة للصف، دافعي عن رأي باحترام، علّمي زميلاتك خطوة بسيطة، أو قدمي اقتراحاً لتحسين الصف. لديها 30 ثانية للاستعداد و60 ثانية للتنفيذ.',link:'الثقة بالنفس تُبنى بالمحاولة والتعبير والمشاركة، لا بادعاء معرفة كل شيء.',evidence:'مشاركة 60 ثانية + نقطة قوة محددة.',impact:'كيف أظهر الثقة من دون أن أقلل من الآخرين؟'},en:{title:'I Can Do It',element:'Traits | Self-Confidence',challenge:'Choose one task shown here: explain a useful class idea, defend an opinion respectfully, teach classmates a simple step, or suggest one classroom improvement. The student gets 30 seconds to prepare and 60 seconds to perform.',link:'Confidence grows through trying, expressing and participating—not pretending to know everything.',evidence:'60-second contribution + one specific strength.',impact:'How can I show confidence without putting others down?'}},
{n:'11',cat:'traits',grades:'5–12',ar:{title:'بطارية التوازن',element:'السمات | الصحة البدنية والنفسية',challenge:'ترسم المجموعة بطارية من 5 مستويات وتضع أنشطة تشحنها وأخرى تستنزفها خلال اليوم الدراسي، ثم تختار عادة صحية صغيرة قابلة للتطبيق.',link:'الصحة البدنية والنفسية تدعم التعلم والتوازن والقدرة على الاستمرار.',evidence:'بطارية شخصية + عادة صحية واحدة.',impact:'ما العادة الصغيرة التي تساعدني على أن أكون أكثر توازناً؟'},en:{title:'Balance Battery',element:'Traits | Physical & Mental Wellbeing',challenge:'Draw a five-level battery showing activities that recharge or drain you during the school day, then select one small healthy habit you can practise.',link:'Physical and mental wellbeing support learning, balance and the ability to keep going.',evidence:'Personal battery + one healthy habit.',impact:'What small habit can help me feel more balanced?'}},
{n:'12',cat:'traits',grades:'5–12',ar:{title:'نافذة ثقافية',element:'السمات | الوعي الثقافي',challenge:'تختار المجموعة عادة أو تحية أو مناسبة من ثقافة تعرفها، وتعرضها باحترام ثم تحدد: ما المختلف؟ وما القيمة الإنسانية المشتركة؟',link:'الوعي الثقافي يعني فهم التنوع باحترام مع الثبات على الهوية والقيم.',evidence:'فرق واحد + قيمة مشتركة واحدة.',impact:'كيف أفهم ثقافة مختلفة دون أن أفقد هويتي؟'},en:{title:'Cultural Window',element:'Traits | Cultural Awareness',challenge:'Choose a custom, greeting or celebration from a culture you know. Present it respectfully, then identify one difference and one shared human value.',link:'Cultural awareness means understanding diversity respectfully while remaining grounded in one’s own identity and values.',evidence:'One difference + one shared value.',impact:'How can I understand another culture without losing my own identity?'}},
{n:'13',cat:'traits',grades:'5–12',ar:{title:'علّميني شيئاً',element:'السمات | التعليم المستمر',challenge:'كل طالبة تختار مهارة صغيرة يمكن تعليمها فوراً دون أدوات خاصة، مثل طريقة للحفظ، تنظيم الوقت، نطق كلمة، اختصار مفيد، أو طريقة حل ذهنية. تتبادل الطالبات التعليم لمدة 5 دقائق ثم تشرح كل واحدة ما تعلمته.',link:'التعليم المستمر يعني أن فرص التعلم لا تنتهي بانتهاء الدرس أو الكتاب.',evidence:'مهارة جديدة + من تعلمتها منه + كيف سأستخدمها.',impact:'ما الشيء الجديد الذي يمكنني تعلمه من شخص حولي؟'},en:{title:'Teach Me Something',element:'Traits | Lifelong Learning',challenge:'Each student chooses a small skill that can be taught immediately with no special materials, such as a memory trick, time-management tip, pronunciation tip, useful shortcut or mental strategy. Students teach one another for five minutes, then explain what they learned.',link:'Lifelong learning means that opportunities to learn do not end with the lesson or textbook.',evidence:'New skill + who taught it + how it can be used.',impact:'What new thing can I learn from someone around me?'}},
{n:'14',cat:'skills',grades:'7–12',ar:{title:'الدليل المفقود',element:'المهارات | التفكير النقدي',challenge:'الادعاء على الشاشة: «القراءة اليومية تحسن التعلم». رتّبوا هذه الأدلة: (أ) «أعتقد أنها مفيدة». (ب) «9 من كل 10 طلاب يتحسنون» بلا مصدر. (ج) سجل صفّي موثق يقارن الأداء قبل وبعد القراءة. (د) رأي صديق. رتبوها من الأقوى إلى الأضعف وفسروا السبب.',link:'التفكير النقدي يعني فحص الادعاءات والأدلة قبل قبولها.',evidence:'ترتيب الأدلة + سبب اختيار الأقوى.',impact:'ما الذي يجعل المعلومة دليلاً وليس مجرد كلام؟'},en:{title:'The Missing Evidence',element:'Future Skills | Critical Thinking',challenge:'Claim on screen: “Daily reading improves learning.” Rank this evidence: (A) “I think it helps.” (B) “9 out of 10 students improve” with no source. (C) A documented class record comparing performance before and after regular reading. (D) A friend’s opinion. Rank strongest to weakest and explain why.',link:'Critical thinking means checking claims and evidence before accepting them.',evidence:'Evidence ranking + reason for the strongest choice.',impact:'What makes information evidence rather than just a statement?'}},
{n:'15',cat:'skills',grades:'5–12',ar:{title:'رسالة في 20 كلمة',element:'المهارات | التواصل الفعال + القراءة والكتابة',challenge:'الموقف جاهز على الشاشة: «سيبدأ نشاط الصف غداً في الحصة الثانية، وعلى الجميع إحضار الدفتر والاستعداد للعمل في مجموعات». اكتبوا رسالة واضحة من 20 كلمة فقط تنقل المطلوب، ثم تختبرها مجموعة أخرى.',link:'التواصل الفعال يجمع بين وضوح الفكرة واختيار الكلمات المناسبة للجمهور.',evidence:'رسالة من 20 كلمة يفهمها الآخرون مباشرة.',impact:'هل كثرة الكلام تعني تواصلاً أفضل؟'},en:{title:'A Message in 20 Words',element:'Future Skills | Effective Communication + Literacy',challenge:'Use this ready-made situation: “Tomorrow’s class activity starts in Period 2. Everyone should bring a notebook and be ready to work in groups.” Write a clear message using exactly 20 words, then let another group test its clarity.',link:'Effective communication combines a clear idea with appropriate language for the audience.',evidence:'A 20-word message that others understand immediately.',impact:'Does using more words always mean better communication?'}},
{n:'16',cat:'skills',grades:'7–12',ar:{title:'AI: استخدم – تحقق – قرر',element:'المهارات | إتقان الذكاء الاصطناعي + التفكير النقدي',challenge:'صنفوا هذه المهام الظاهرة إلى استخدم – تحقق – قرر: توليد أفكار لمشروع، تلخيص نص، معلومة صحية، حل رياضي، اختيار عقوبة لطالبة، كتابة قرار أخلاقي. ثم اكتبوا قاعدة واحدة للاستخدام المسؤول.',link:'إتقان الذكاء الاصطناعي يعني استخدامه بوعي والتحقق من مخرجاته وتحمل مسؤولية القرار.',evidence:'موقف مصنف إلى استخدم/تحقق/قرر + قاعدة مسؤولة.',impact:'ما الذي لا ينبغي أن أفوضه للذكاء الاصطناعي؟'},en:{title:'AI: Use – Verify – Decide',element:'Future Skills | AI Mastery + Critical Thinking',challenge:'Classify these ready-made tasks into Use – Verify – Decide: generate project ideas, summarize a text, health information, solve a maths problem, choose a punishment for a student, make an ethical decision. Then write one responsible-use rule.',link:'AI mastery means using it thoughtfully, checking its outputs and remaining responsible for final decisions.',evidence:'Use/Verify/Decide classification + one responsible-use rule.',impact:'What should I never delegate completely to AI?'}},
{n:'17',cat:'skills',grades:'7–12',ar:{title:'أصلحي الـ Prompt',element:'المهارات | إتقان الذكاء الاصطناعي + التواصل الفعال',challenge:'الـ Prompt الضعيف موجود على الشاشة: «اكتب عن البيئة». حسّنوه بإضافة خمسة عناصر: الهدف، الجمهور، المهمة المحددة، شكل الإجابة، وقيد واحد مثل عدد الكلمات أو مستوى اللغة.',link:'الاستخدام الجيد للذكاء الاصطناعي يحتاج إلى تواصل دقيق وتحديد واضح للمهمة.',evidence:'Prompt محسن يحتوي 5 عناصر.',impact:'كيف يغير وضوح طلبي جودة النتيجة؟'},en:{title:'Fix the Prompt',element:'Future Skills | AI Mastery + Effective Communication',challenge:'The weak prompt is already on screen: “Write about the environment.” Improve it by adding five elements: purpose, audience, specific task, response format and one constraint such as word count or language level.',link:'Good AI use depends on precise communication and a clearly defined task.',evidence:'Improved prompt containing five key elements.',impact:'How does a clearer request improve the quality of the result?'}},
{n:'18',cat:'skills',grades:'5–12',ar:{title:'اختراع من ثلاثة أشياء',element:'المهارات | الإبداع',challenge:'اختاروا رقماً من 1 إلى 4 لكل عمود: الغرض: زجاجة/مشبك/حقيبة/كرسي. المكان: صف/حافلة/مكتبة/ساحة. المشكلة: ضوضاء/هدر ماء/نسيان/ازدحام. ابتكروا حلاً يجمع الكلمات الثلاث واشرحوا فائدته.',link:'الإبداع هو القدرة على توليد أفكار جديدة وتحويلها إلى حلول ذات فائدة.',evidence:'رسم الحل + المشكلة التي يحلها.',impact:'كيف أحول فكرة غريبة إلى حل مفيد؟'},en:{title:'Invent from Three Things',element:'Future Skills | Creativity',challenge:'Choose a number from 1–4 in each column. Object: bottle / clip / bag / chair. Place: classroom / bus / library / playground. Problem: noise / water waste / forgetting / crowding. Invent one solution that connects all three and explain its benefit.',link:'Creativity is the ability to generate new ideas and turn them into useful solutions.',evidence:'Solution sketch + the problem it solves.',impact:'How can a strange idea become a useful solution?'}},
{n:'19',cat:'skills',grades:'5–12',ar:{title:'100 درهم فقط',element:'المهارات | الثقافة المالية + المهارات الحسابية',challenge:'لديكم 100 درهم لنشاط صفّي. الأسعار على الشاشة: مواد أساسية 40، زينة 25، وجبة خفيفة 30، احتياطي 20. اختاروا ميزانية لا تتجاوز 100. ثم ظهر مصروف مفاجئ 15 درهماً: أعيدوا التوزيع وفسروا قراركم.',link:'الثقافة المالية والحساب تساعدان المتعلم على اتخاذ قرارات مسؤولة وفق الموارد المتاحة.',evidence:'ميزانية مجموعها 100 + تعديل بعد المفاجأة.',impact:'كيف أميز بين ما أحتاجه وما أرغب فيه؟'},en:{title:'Only 100 Dirhams',element:'Future Skills | Financial Literacy + Numeracy',challenge:'You have AED 100 for a class activity. Prices on screen: essential materials 40, decorations 25, snacks 30, reserve 20. Build a budget that does not exceed 100. Then an unexpected AED 15 cost appears: rebalance and explain your decision.',link:'Financial literacy and numeracy help learners make responsible decisions within available resources.',evidence:'Balanced AED 100 budget + revised version.',impact:'How do I distinguish between what I need and what I want?'}},
{n:'20',cat:'skills',grades:'7–12',ar:{title:'الخبر قبل النشر',element:'المهارات | التفكير النقدي + التواصل الفعال',challenge:'الرسالة على الشاشة: «عاجل: غداً لا توجد حصص! أرسليها للجميع الآن». لا يوجد مصدر أو تاريخ أو إعلان رسمي. افحصوا أربع بوابات: المصدر، التاريخ، الدليل، والضرر المحتمل. ثم قرروا: أنشر، أتحقق، أم أتوقف؟',link:'يجمع الميثاق بين التفكير الواعي والتواصل المسؤول في التعامل مع المعلومات.',evidence:'قرار نشر مبرر بأربع بوابات.',impact:'هل كل معلومة مثيرة تستحق المشاركة؟'},en:{title:'Before You Share',element:'Future Skills | Critical Thinking + Effective Communication',challenge:'Message on screen: “URGENT: There are no classes tomorrow! Send this to everyone now.” It has no source, date or official announcement. Check four gates: source, date, evidence and possible harm. Then decide: share, verify or stop.',link:'The Charter combines thoughtful reasoning with responsible communication when handling information.',evidence:'A sharing decision justified by four checks.',impact:'Does every exciting piece of information deserve to be shared?'}},
{n:'21',cat:'skills',grades:'5–12',ar:{title:'قصة في ست كلمات',element:'المهارات | القراءة والكتابة + الإبداع',challenge:'اختاروا عنصراً من جدار كلمات الميثاق داخل الموقع، ثم اكتبوا قصة من ست كلمات فقط تجعله واضحاً دون ذكر اسمه. يحاول الصف اكتشاف العنصر.',link:'تجمع المهمة بين التعبير اللغوي والإبداع وفهم عناصر الميثاق في سياق واقعي.',evidence:'قصة من 6 كلمات + عنصر الميثاق المقصود.',impact:'كيف أُظهر القيمة في قصة دون أن أذكر اسمها؟'},en:{title:'A Six-Word Story',element:'Future Skills | Literacy + Creativity',challenge:'Choose any element from the website’s Charter Word Wall, then write a six-word story that makes it visible without naming it. The class tries to identify the element.',link:'The task combines concise language, creativity and real understanding of Charter elements in context.',evidence:'Six-word story + intended Charter element.',impact:'How can I show a value in a story without naming it?'}},
{n:'22',cat:'multi',grades:'5–9',ar:{title:'الميثاق يتحرك',element:'متعدد المحاور | الهوية + السمات + المهارات',challenge:'اختاري موقفاً من الشاشة ومثليه في 30 ثانية بلا كلام: مساعدة زميلة، حل خلاف داخل فريق، الاعتراف بخطأ، تغيير الخطة بعد مشكلة، أو التحقق من معلومة. على الصف تحديد عنصر الميثاق وذكر الدليل.',link:'هدف الميثاق أن تظهر عناصره في المواقف والسلوك، لا أن تبقى أسماء نحفظها.',evidence:'تمثيل + تحديد عنصر + دليل من المشهد.',impact:'كيف أعرف أن شخصاً يطبق الميثاق من سلوكه؟'},en:{title:'The Charter in Motion',element:'Cross-Pillar | Identity + Traits + Skills',challenge:'Choose one scenario shown here and act it silently for 30 seconds: helping a classmate, resolving a team disagreement, admitting a mistake, adapting a plan after a problem, or checking information before sharing. The class identifies the Charter element and evidence.',link:'The Charter is meant to appear in real behaviour and situations, not remain as terms to memorise.',evidence:'Silent scene + identified Charter element + evidence.',impact:'How can I tell that someone is applying the Charter through behaviour?'}},
{n:'23',cat:'multi',grades:'7–12',ar:{title:'مهمة الثلاثة',element:'متعدد المحاور | عنصر من كل ركيزة',challenge:'تختار المجموعة مشكلة مدرسية حقيقية. لا يُقبل الحل إلا إذا تضمن قيمة من الهوية الوطنية، سمة شخصية ومهارة مستقبلية.',link:'يرسم الميثاق ملامح متعلم متكامل؛ لذلك تعمل الهوية والسمات والمهارات معاً.',evidence:'مثلث الميثاق + حل عملي.',impact:'كيف تتكامل الركائز الثلاث لصناعة أثر؟'},en:{title:'The Power of Three',element:'Cross-Pillar | One Element from Each Pillar',challenge:'Choose a real school problem. A solution is only accepted if it includes one National Identity value, one personal trait and one future skill.',link:'The Charter describes a well-rounded learner, so identity, traits and skills work together in the same situation.',evidence:'Charter triangle + practical solution.',impact:'How do the three pillars work together to create impact?'}},
{n:'24',cat:'multi',grades:'5–12',ar:{title:'بطاقة الأثر الحقيقي',element:'متعدد المحاور | تطبيق الميثاق في الحياة المدرسية',challenge:'اختاري الآن فعلاً صغيراً يمكن تنفيذه خلال هذه الحصة: ساعدي زميلة، رتبي مساحة مشتركة، ابدئي مهمة دون انتظار، استمعي لزميلة باحترام، أو تحققي من معلومة قبل تكرارها. نفذي الفعل خلال 5 دقائق ثم شاركي: ما العنصر؟ وما الأثر الذي ظهر؟',link:'نجاح الميثاق يقاس بحضوره في الممارسات اليومية وتحويل القيم والسمات والمهارات إلى أثر إيجابي.',evidence:'فعل حقيقي + عنصر الميثاق + أثر يمكن ملاحظته.',impact:'ما الذي تغير لأنني طبقت الميثاق؟'},en:{title:'Real Impact Card',element:'Cross-Pillar | Applying the Charter in School Life',challenge:'Choose one small Charter action that can be completed during this lesson: help a classmate, organize a shared space, start a useful task without waiting, listen respectfully to someone, or verify information before repeating it. Do it within five minutes, then share: which element did it show and what impact was visible?',link:'The Charter succeeds when its values, traits and skills appear in everyday practice and create positive impact.',evidence:'Real action + Charter element + observable impact.',impact:'What changed because I applied the Charter?'}}
];

const COLORS={national:'#b88a32',traits:'#2e7d78',skills:'#6f5a94',multi:'#6f171b'};
const SOFT={national:'#fff8e8',traits:'#eaf7f5',skills:'#f4f0fa',multi:'#f7eeee'};
// Live approved Top 3 results are read automatically from GitHub Issue #1.
const TOP3_ISSUE_API='https://api.github.com/repos/saidahkhwar11-lang/charter-impact/issues/1';
const AMBASSADOR_TERMS={term1:{},term2:{},term3:{}};
let activeAmbassadorTerm='term1';
let ambassadorsLoaded=false,ambassadorsLoading=null;

function blankGradeData(){
  return {5:[],6:[],7:[],8:[],9:[],10:[],11:[],12:[]};
}
function normalizeTermRows(rows){
  const data=blankGradeData();
  (Array.isArray(rows)?rows:[]).forEach(row=>{
    const grade=String(row?.grade??'').trim();
    if(!Object.prototype.hasOwnProperty.call(data,grade))return;
    ['first','second','third'].forEach(key=>{
      const name=String(row?.[key]??'').trim();
      if(name) data[grade].push({name});
    });
  });
  return data;
}
function normalizeTop3(payload){
  // New format: {term1:[...],term2:[...],term3:[...]}
  if(payload && !Array.isArray(payload) && typeof payload==='object'){
    AMBASSADOR_TERMS.term1=normalizeTermRows(payload.term1);
    AMBASSADOR_TERMS.term2=normalizeTermRows(payload.term2);
    AMBASSADOR_TERMS.term3=normalizeTermRows(payload.term3);
  }else{
    // Backward compatibility with the previous single-array format.
    AMBASSADOR_TERMS.term1=normalizeTermRows(payload);
    AMBASSADOR_TERMS.term2=blankGradeData();
    AMBASSADOR_TERMS.term3=blankGradeData();
  }
}
function currentSchoolTerm(){
  const now=new Date();
  const y=now.getFullYear(),m=now.getMonth()+1,d=now.getDate();
  if((y===2026 && (m>9 || (m===9&&d>=1)) && (m<11 || (m===11&&d<=15)))) return 'term1';
  if((y===2027 && (m>1 || (m===1&&d>=4)) && (m<3 || (m===3&&d<=15)))) return 'term2';
  if((y===2027 && (m>4 || (m===4&&d>=15)) && (m<6 || (m===6&&d<=10)))) return 'term3';
  // Outside the active windows, keep the most recently relevant school term.
  if(y<2027) return 'term1';
  if(m<4) return 'term2';
  return 'term3';
}
activeAmbassadorTerm=currentSchoolTerm();

async function loadAmbassadors(){
  if(ambassadorsLoaded)return;
  if(ambassadorsLoading)return ambassadorsLoading;
  ambassadorsLoading=(async()=>{
    try{
      const cacheKey='charterTop3CacheV2',cached=localStorage.getItem(cacheKey);
      if(cached){
        const c=JSON.parse(cached);
        if(Date.now()-c.time<300000){normalizeTop3(c.data);ambassadorsLoaded=true;return;}
      }
      const res=await fetch(TOP3_ISSUE_API,{headers:{Accept:'application/vnd.github+json'},cache:'no-store'});
      if(!res.ok)throw new Error('GitHub '+res.status);
      const issue=await res.json();
      const payload=JSON.parse((issue.body||'{}').trim());
      normalizeTop3(payload);
      localStorage.setItem(cacheKey,JSON.stringify({time:Date.now(),data:payload}));
      ambassadorsLoaded=true;
    }catch(err){console.warn('Top 3 data could not be loaded:',err);}
    finally{ambassadorsLoading=null;}
  })();
  return ambassadorsLoading;
}
let lang='ar',filter='all',cardsLoaded=false,currentCard=null;
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
function t(k){return I18N[lang][k]||k}
function applyLanguage(){
  document.documentElement.lang=lang;document.documentElement.dir=lang==='ar'?'rtl':'ltr';
  $$('[data-i18n]').forEach(el=>el.innerHTML=t(el.dataset.i18n));
  $$('[data-i18n-placeholder]').forEach(el=>el.placeholder=t(el.dataset.i18nPlaceholder));
  $('#langToggle').textContent=lang==='ar'?'EN':'عربي';
  if(cardsLoaded) renderCards();
  if($('#cardModal').classList.contains('show')&&currentCard) openCard(currentCard);
  if($('#nominationModal').classList.contains('show')) renderNominationContext();
  if(!$('#ambassadorsPanel').hidden) renderAmbassadors();
}
function openPanel(id){
  $$('.content-panel').forEach(p=>p.hidden=true);
  const panel=document.getElementById(id); if(!panel)return; panel.hidden=false;
  if(id==='cardsPanel'&&!cardsLoaded){cardsLoaded=true;renderCards();}
  if(id==='gamesPanel') renderGames();
  if(id==='ambassadorsPanel') renderAmbassadors();
  panel.scrollIntoView({behavior:'smooth',block:'start'});
}

async function renderAmbassadors(){
  const grid=$('#ambassadorsGrid'); if(!grid)return;
  if(!ambassadorsLoaded){
    grid.innerHTML=`<div class="ranking-loading">${lang==='ar'?'جارٍ تحديث قائمة سفيرات الميثاق…':'Updating Charter Ambassadors…'}</div>`;
    await loadAmbassadors();
  }
  $$('.term-filter').forEach(btn=>{
    btn.textContent=t(btn.dataset.term);
    btn.classList.toggle('active',btn.dataset.term===activeAmbassadorTerm);
    btn.setAttribute('aria-pressed',btn.dataset.term===activeAmbassadorTerm?'true':'false');
  });
  const termData=AMBASSADOR_TERMS[activeAmbassadorTerm]||blankGradeData();
  grid.innerHTML='';
  Object.keys(termData).forEach(grade=>{
    const students=termData[grade]||[];
    const card=document.createElement('article'); card.className='grade-ranking';
    const rows=[0,1,2].map((i)=>{const st=students[i]; const place=t('place'+(i+1)); return `<div class="rank-row"><b>${i+1}</b><span><strong>${st?.name||t('waiting')}</strong></span><em>${place}</em></div>`}).join('');
    card.innerHTML=`<h4>${lang==='ar'?'الصف':'Grade'} ${grade}</h4>${rows}`; grid.appendChild(card);
  });
}

function renderCards(){
  const q=($('#cardSearch')?.value||'').trim().toLowerCase(),grid=$('#cardsGrid'); if(!grid)return;
  grid.innerHTML='';
  cards.filter(c=>filter==='all'||c.cat===filter).filter(c=>{const d=c[lang];return !q||(`${d.title} ${d.element} ${d.challenge}`).toLowerCase().includes(q)}).forEach(c=>{
    const d=c[lang],el=document.createElement('article');el.className='challenge-card';el.style.setProperty('--card-color',COLORS[c.cat]);
    el.innerHTML=`<div class="card-strip"></div><div class="card-body"><div class="card-meta"><span class="card-number">#${c.n}</span><span class="card-grade">${t('grade')} ${c.grades}</span></div><h3>${d.title}</h3><div class="charter-tag">${d.element}</div><p>${d.challenge}</p><div class="open-card">${t('openCard')} ←</div></div>`;
    el.addEventListener('click',()=>openCard(c));grid.appendChild(el);
  });
}
function openCard(c){
  currentCard=c;const d=c[lang],m=$('#cardModal');m.style.setProperty('--modal-color',COLORS[c.cat]);m.style.setProperty('--modal-soft',SOFT[c.cat]);
  $('#modalContent').innerHTML=`<span class="modal-kicker">#${c.n} • ${t('grade')} ${c.grades}</span><h2>${d.title}</h2><span class="modal-element">${d.element}</span><div class="modal-block highlight"><h4>${t('modalChallenge')}</h4><p>${d.challenge}</p></div><div class="modal-block"><h4>${t('modalLink')}</h4><p>${d.link}</p></div><div class="modal-block"><h4>${t('modalEvidence')}</h4><p>${d.evidence}</p></div><div class="modal-block highlight"><h4>${t('modalImpact')}</h4><p>${d.impact}</p></div>`;
  m.classList.add('show');m.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';
}
function closeCardModal(){const m=$('#cardModal');m.classList.remove('show');m.setAttribute('aria-hidden','true');document.body.style.overflow=''}
function openNomination(card=null){currentCard=card;renderNominationContext();const m=$('#nominationModal');m.classList.add('show');m.setAttribute('aria-hidden','false');document.body.style.overflow='hidden';}
function closeNomination(){const m=$('#nominationModal');m.classList.remove('show');m.setAttribute('aria-hidden','true');document.body.style.overflow=''}
function renderNominationContext(){const box=$('#nominationContext');if(!currentCard){box.classList.remove('show');box.innerHTML='';return}const d=currentCard[lang];box.classList.add('show');box.innerHTML=`<strong>${t('contextChallenge')} #${currentCard.n}: ${d.title}</strong><br>${d.element}<br><small>${t('contextAuto')}</small>`;}
$('#langToggle').addEventListener('click',()=>{lang=lang==='ar'?'en':'ar';applyLanguage()});
$('#printBtn').addEventListener('click',()=>window.print());
$$('.hub-card').forEach(b=>b.addEventListener('click',()=>{$$('.hub-card').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');openPanel(b.dataset.panel)}));
$$('[data-close-panel]').forEach(b=>b.addEventListener('click',()=>{b.closest('.content-panel').hidden=true;$$('.hub-card').forEach(x=>x.classList.remove('selected'))}));
$('#cardSearch').addEventListener('input',()=>{if(cardsLoaded)renderCards()});
$$('.filter').forEach(btn=>btn.addEventListener('click',()=>{$$('.filter').forEach(b=>b.classList.remove('active'));btn.classList.add('active');filter=btn.dataset.filter;renderCards()}));
$$('[data-close-card-modal]').forEach(el=>el.addEventListener('click',closeCardModal));
$$('[data-close-nomination]').forEach(el=>el.addEventListener('click',closeNomination));
$('#generalNominationBtn').addEventListener('click',()=>openNomination(null));
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeCardModal();closeNomination()}});
applyLanguage();


// Term selector for the Charter Ambassadors leaderboard.
document.addEventListener('click',function(e){
  const btn=e.target.closest('.term-filter');
  if(!btn)return;
  const term=btn.dataset.term;
  if(!['term1','term2','term3'].includes(term))return;
  activeAmbassadorTerm=term;
  renderAmbassadors();
});


